-- Create the schemes table in Supabase
create table if not exists public.schemes (
  scheme_id integer primary key,
  scheme_name text not null,
  ministry_department text,
  category text,
  launch_year text,
  objective text,
  target_beneficiaries text,
  benefits text,
  state text,
  eligibility text,
  documents_required text,
  official_resource text,
  created_at timestamp with time zone default timezone('utc'::text, now()) not null
);

-- Enable RLS
alter table public.schemes enable row level security;
create policy "Allow public read on schemes" on public.schemes for select using (true);
create policy "Allow all on schemes for demo" on public.schemes for all using (true) with check (true);

-- Insert all 100 agricultural schemes
